{"tool": "write_file", "args": {"path": "scripts/resend_failed_sms.py", "content": """"LIFE-209: re-send SMS messages that failed at the gateway last cycle.

Reads data/sms_status.json to find failed messages, re-queues exactly one new
message per failed SMS (same household, same template/params/text) using the
existing send function in notifications/sms.py, and appends audit entries.
Delivered messages are never re-sent. Safe to re-run: households already
re-sent (per audit) are skipped.
"""
import json
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from config.settings import now as _now  # noqa: E402
from core import store  # noqa: E402
from notifications.sms import queue_sms, sent_messages  # noqa: E402

ACTOR = "scripts/resend_failed_sms.py"


def main() -> None:
    status = store.read_json("sms_status.json")
    messages = {m.id: m for m in sent_messages()}

    already_resent = set()
    for entry in store.read_jsonl("audit.jsonl"):
        if entry.get("event") == "sms_resend":
            already_resent.add(entry.get("ref"))

    failed_ids = [sid for sid, s in status.items() if s == "failed"]
    delivered_ids = {sid for sid, s in status.items() if s == "delivered"}

    sent = []
    for sid in failed_ids:
        if sid in already_resent:
            print(f"skip {sid}: already re-sent")
            continue
        original = messages.get(sid)
        if original is None:
            print(f"skip {sid}: no outbox entry found")
            continue
        new_msg = queue_sms(original.household_id, original.template_id, dict(original.params))
        store.append_jsonl("audit.jsonl", {
            "event": "sms_resend",
            "actor": ACTOR,
            "ref": sid,
            "new_sms": new_msg.id,
            "household_id": original.household_id,
            "at": _now().isoformat(timespec="seconds"),
        })
        sent.append((sid, new_msg))
        print(f"re-sent {sid} as {new_msg.id} to {original.household_id}: {new_msg.text}")

    # Verification: exactly one new text per failed household, none to delivered households.
    outbox = sent_messages()
    resent_original_ids = {sid for sid, _ in sent} | already_resent
    expected_households = {messages[sid].household_id for sid in resent_original_ids if sid in messages}
    delivered_households = {messages[sid].household_id for sid in delivered_ids if sid in messages}
    new_msgs = [m for m in outbox if m.id not in messages]
    per_household = {}
    problems = []
    for m in new_msgs:
        per_household[m.household_id] = per_household.get(m.household_id, 0) + 1
        if m.household_id in delivered_households:
            problems.append(f"delivered household {m.household_id} was texted ({m.id})")
    for hh in expected_households:
        if per_household.get(hh, 0) != 1:
            problems.append(f"household {hh} has {per_household.get(hh, 0)} new texts, expected 1")

    print(f"failed: {len(failed_ids)}, re-sent now: {len(sent)}")
    if problems:
        print("VERIFICATION PROBLEMS:")
        for p in problems:
            print(" - " + p)
        sys.exit(1)
    print("verification OK: one new text per failed household, no delivered household texted")


if __name__ == "__main__":
    main()
